<?php require_once 'auth.php';requiereAdmin();$rows=$conexion->query('SELECT c.*,u.usuario FROM clientes c LEFT JOIN usuario u ON u.idUsuario=c.idUsuario ORDER BY c.idCliente DESC')->fetchAll();encabezado('Clientes registrados');?><div class="table-wrap"><table><tr><th>Nombre</th><th>Usuario</th><th>Teléfono</th><th>Correo</th><th>Dirección</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['usuario']??'—')?></td><td><?=e($r['telefono'])?></td><td><?=e($r['correo'])?></td><td><?=e($r['direccion'])?></td></tr><?php endforeach;?></table></div><?php pie();?>